<template>
    <div class="accounts-page">
        <header class="manager-heading"><div><span class="eyebrow">TÀI KHOẢN & PHÂN QUYỀN</span><h2>{{ permissionsMode ? 'Phân quyền theo vai trò' : 'Quản lý tài khoản' }}</h2><p>{{ permissionsMode ? 'Gán vai trò cho tài khoản theo phạm vi chức năng của nhà hàng.' : 'Quản lý tài khoản khách hàng và nhân viên.' }}</p></div><button class="manager-button primary" :disabled="loading" @click="edit()">Thêm tài khoản</button></header>
        <section v-if="permissionsMode" class="roles-grid"><article v-for="r in roles" :key="r.code"><h3>{{ r.name }}</h3><p>{{ r.users_count }} tài khoản</p><ul><li v-for="s in r.scopes" :key="s">{{ s }}</li></ul><button class="manager-button" @click="filter.role = r.code; load(1)">Xem tài khoản</button></article></section>
        <p v-if="permissionsMode" class="manager-notice">Quyền truy cập hiện được quy định theo 6 vai trò cố định. Chọn “Phân quyền” để gán vai trò cho tài khoản; chưa hỗ trợ tạo vai trò hoặc sửa quyền riêng lẻ.</p>
        <form class="filters" @submit.prevent="load(1)"><input v-model="filter.search" placeholder="Tìm tên, email hoặc số điện thoại…" aria-label="Tìm tài khoản" maxlength="150" /><select v-model="filter.role" aria-label="Vai trò"><option value="">Tất cả vai trò</option><option v-for="r in roles" :key="r.code" :value="r.code">{{ r.name }}</option></select><select v-model="filter.active" aria-label="Trạng thái"><option value="">Tất cả trạng thái</option><option value="1">Hoạt động</option><option value="0">Đã khóa</option></select><button class="manager-button" :disabled="loading">Tra cứu / Làm mới</button></form>
        <p v-if="success" class="manager-notice" role="status">{{ success }}</p><p v-if="error" class="manager-notice error" role="alert">{{ error }}</p><p v-if="loading" role="status">Đang tải tài khoản…</p><template v-else-if="!error"><p class="result-count">{{ total }} tài khoản phù hợp</p><div v-if="accounts.length" class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Liên hệ</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="u in accounts" :key="u.id"><td><strong>{{ u.name }}</strong><small>Mã #{{ u.id }}{{ u.id === staff.currentUserId ? ' · Bạn' : '' }}</small></td><td>{{ u.email }}<small>{{ u.phone || 'Chưa có số điện thoại' }}</small></td><td>{{ u.roles.map(roleName).join(', ') || 'Chưa gán vai trò' }}</td><td>{{ u.is_active ? 'Hoạt động' : 'Đã khóa' }}</td><td><button class="manager-button" @click="edit(u)">{{ permissionsMode ? 'Phân quyền' : 'Chỉnh sửa' }}</button></td></tr></tbody></table></div><p v-else class="manager-notice">Không có tài khoản phù hợp.</p><div v-if="lastPage > 1" class="pagination"><button :disabled="page <= 1" @click="load(page - 1)">Trước</button><span>{{ page }} / {{ lastPage }}</span><button :disabled="page >= lastPage" @click="load(page + 1)">Sau</button></div></template>
        <dialog ref="dialog" @cancel="cancel"><form @submit.prevent="save"><header><h3>{{ editingId ? 'Cập nhật tài khoản' : 'Tạo tài khoản' }}</h3><button type="button" :disabled="saving" @click="dialog?.close()">Đóng</button></header><div class="form-body"><p v-if="formError" class="manager-notice error" role="alert">{{ formError }}</p><fieldset :disabled="saving"><label>Họ tên<input v-model="form.name" required maxlength="100" autocomplete="off" /></label><label>Email<input v-model="form.email" type="email" required maxlength="150" autocomplete="off" /></label><label>Số điện thoại<input v-model="form.phone" type="tel" maxlength="20" /></label><label>Vai trò<select v-model="form.role" required :disabled="editingId === staff.currentUserId"><option value="" disabled>Chọn vai trò</option><option v-for="r in roles" :key="r.code" :value="r.code">{{ r.name }}</option></select></label><p class="help">Mỗi tài khoản được gán một vai trò. Đổi vai trò sẽ thu hồi phiên đăng nhập cũ.</p><label v-if="form.role === 'KITCHEN'" class="check"><input v-model="form.can_close_daily_stock" type="checkbox" /> Bếp trưởng được chốt sổ kho ngày</label><label class="check"><input v-model="form.is_active" type="checkbox" :disabled="editingId === staff.currentUserId" /> Cho phép đăng nhập</label><label>{{ editingId ? 'Mật khẩu mới (bỏ trống để giữ nguyên)' : 'Mật khẩu' }}<input v-model="form.password" type="password" :required="!editingId" minlength="8" maxlength="128" autocomplete="new-password" /></label><label>Xác nhận mật khẩu<input v-model="form.password_confirmation" type="password" :required="!!form.password" maxlength="128" autocomplete="new-password" /></label><p class="help">Ít nhất 8 ký tự, gồm chữ và số. Đặt lại mật khẩu sẽ đăng xuất các phiên hiện tại.</p></fieldset></div><footer><button type="button" class="manager-button" :disabled="saving" @click="dialog?.close()">Hủy</button><button class="manager-button primary" :disabled="saving">{{ saving ? 'Đang lưu…' : 'Lưu tài khoản' }}</button></footer></form></dialog>
    </div>
</template>
<script setup lang="ts">
import { beginRead } from '@/utils/realtime'
const liveReads = {}
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useStaffStore } from '@/stores/staff'
import api from '@/api/client'
interface Account { id: number; name: string; email: string; phone: string | null; roles: string[]; is_active: boolean; can_close_daily_stock: boolean }
interface RoleInfo { code: string; name: string; scopes: string[]; users_count: number }
const route = useRoute(), staff = useStaffStore(), permissionsMode = computed(() => route.path.endsWith('/permissions'))
const roles = ref<RoleInfo[]>([]), accounts = ref<Account[]>([]), total = ref(0), page = ref(1), lastPage = ref(1), loading = ref(false), error = ref(''), success = ref('')
const filter = reactive({ search: '', role: '', active: '' }); let applied = { ...filter }, requestId = 0
const dialog = ref<HTMLDialogElement>(), editingId = ref<number | null>(null), saving = ref(false), formError = ref('')
const form = reactive({ name: '', email: '', phone: '', role: '', is_active: true, can_close_daily_stock: false, password: '', password_confirmation: '' })
const roleName = (code: string) => roles.value.find(r => r.code === code)?.name || code
async function load(p = 1, quiet = false) { const id = ++requestId; if (p === 1 && !quiet) applied = { ...filter }; if (!quiet) loading.value = true; if (!quiet) error.value = ''; const fresh = beginRead(liveReads, 'list', quiet); try { const [users, r] = await Promise.all([api.get('/staff/dashboard/accounts', { params: { ...applied, page: p } }), api.get('/staff/dashboard/roles')]); if (!fresh() || id !== requestId) return; error.value = ""; accounts.value = users.data.data; total.value = users.data.total; page.value = users.data.current_page; lastPage.value = users.data.last_page; roles.value = r.data.data } catch (refreshError) { if (quiet) throw refreshError; if (id === requestId) error.value = 'Không tải được tài khoản. Vui lòng thử lại.' } finally { if (id === requestId) if (!quiet) loading.value = false } }
function edit(u?: Account) { editingId.value = u?.id ?? null; Object.assign(form, { name: u?.name || '', email: u?.email || '', phone: u?.phone || '', role: u?.roles.length === 1 ? u.roles[0] : '', is_active: u?.is_active ?? true, can_close_daily_stock: u?.can_close_daily_stock ?? false, password: '', password_confirmation: '' }); formError.value = u && u.roles.length > 1 ? 'Tài khoản đang có nhiều vai trò. Chọn vai trò duy nhất để chuẩn hóa quyền truy cập.' : ''; dialog.value?.showModal() }
function cancel(e: Event) { if (saving.value) e.preventDefault() }
async function save() { if (saving.value) return; if (form.password !== form.password_confirmation) { formError.value = 'Mật khẩu xác nhận chưa khớp.'; return }; saving.value = true; formError.value = ''; try { const payload = { ...form, phone: form.phone || null, password: form.password || undefined, password_confirmation: form.password ? form.password_confirmation : undefined }; if (editingId.value) await api.patch('/staff/dashboard/accounts/' + editingId.value, payload); else await api.post('/staff/dashboard/accounts', payload); dialog.value?.close(); form.password = ''; form.password_confirmation = ''; success.value = 'Đã lưu tài khoản và vai trò.'; await load(page.value) } catch (e: any) { formError.value = Object.values(e?.response?.data?.errors || {}).flat().join(' ') || e?.response?.data?.message || 'Không lưu được tài khoản.' } finally { saving.value = false } }
watch(() => route.path, () => { dialog.value?.close(); filter.role = ''; filter.search = ''; filter.active = ''; success.value = ''; void load() })
onMounted(() => load())
useRealtimeRefresh(() => load(page.value, true), () => !loading.value && !saving.value)
</script>
<style scoped>
.accounts-page { display:flex;flex-direction:column;gap:18px; }.roles-grid { display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px; }.roles-grid article { padding:20px;background:white;border:1px solid var(--color-border);border-radius:12px; }.roles-grid h3 { margin:0;font-size:16px; }.roles-grid p,.roles-grid li { font-size:13px;color:#64748b;line-height:1.8; }.roles-grid ul { padding-left:18px; }.filters { display:flex;gap:12px;flex-wrap:wrap; }.filters input { flex:1;min-width:200px; }input,select { padding:11px;border:1px solid var(--color-border-strong);border-radius:7px;font:inherit;min-width:0; }.table-wrap { overflow-x:auto;background:white;border:1px solid var(--color-border);border-radius:12px; }table { width:100%;min-width:740px;border-collapse:collapse;font-size:13px; }th,td { padding:16px;text-align:left;border-bottom:1px solid #e2e8f0; }th { background:var(--color-brand-soft);color:#64748b; }small { display:block;color:#64748b;margin-top:6px; }.pagination { display:flex;justify-content:flex-end;gap:12px; }.primary { background:var(--color-brand-action);color:white; }dialog { width:min(560px,calc(100% - 32px));max-height:90vh;padding:0;border:0;border-radius:14px;color:var(--color-text);font:14px var(--font-ui); }dialog::backdrop { background:color-mix(in srgb, var(--color-brand-dark) 75%, transparent); }dialog header,dialog footer { padding:18px 24px;display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid #e2e8f0; }dialog h3 { margin:0; }dialog footer { justify-content:flex-end; }.form-body { padding:24px; }fieldset { border:0;padding:0;margin:0;display:flex;flex-direction:column;gap:16px; }label { display:flex;flex-direction:column;gap:8px; }.check { flex-direction:row;align-items:center; }.help { font-size:12px;color:#64748b;line-height:1.7; }button { cursor:pointer; }button:disabled { opacity:.5;cursor:not-allowed; }
</style>
